const settleB2BInvoice = `-- name: SettleB2BInvoice :one
UPDATE b2b_invoices
SET status = $2,
    paid_at = CASE WHEN $2 = 'paid' THEN NOW() ELSE paid_at END,
    updated_at = NOW()
WHERE id = $1 AND status = 'open'
RETURNING id, company_id, order_id, number, amount_cents, status, due_at, paid_at, created_at, updated_at
`

type SettleB2BInvoiceParams struct {
	ID     uuid.UUID `json:"id"`
	Status string    `json:"status"`
}

// SettleB2BInvoice flips an OPEN invoice to paid/void atomically - the
// WHERE guard makes double-settlement return no row instead of
// double-releasing credit
func (q *Queries) SettleB2BInvoice(ctx context.Context, arg SettleB2BInvoiceParams) (B2bInvoice, error) {
	row := q.db.QueryRowContext(ctx, settleB2BInvoice, arg.ID, arg.Status)
	var i B2bInvoice
	err := row.Scan(
		&i.ID,
		&i.CompanyID,
		&i.OrderID,
		&i.Number,
		&i.AmountCents,
		&i.Status,
		&i.DueAt,
		&i.PaidAt,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

